CREATE TABLE IF NOT EXISTS shopease_order.checkout_attempts (id VARCHAR(128) PRIMARY KEY,kind VARCHAR(20) NOT NULL,request_hash VARCHAR(64) NOT NULL,snapshot LONGTEXT NOT NULL,order_id BIGINT,state VARCHAR(20) NOT NULL,error VARCHAR(500),attempts INT NOT NULL,next_attempt_at DATETIME(6),version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS shopease_order.service_outbox (id VARCHAR(128) PRIMARY KEY,target VARCHAR(255) NOT NULL,payload LONGTEXT NOT NULL,delivered BIT(1) NOT NULL,attempts INT NOT NULL,created_at DATETIME(6),next_attempt_at DATETIME(6),last_error VARCHAR(120));
